// Leitura compartilhada da matriz compactada (4 bits/celula, y invertido)
static inline uint8_t level_get_block(const uint8_t level[], uint8_t x, uint8_t y) {
  if (x >= LEVEL_WIDTH || y >= LEVEL_HEIGHT) {
    return E_FLOOR;
  }

  return (pgm_read_byte(level + (((uint16_t)(LEVEL_HEIGHT - 1 - y) * LEVEL_WIDTH + x) / 2))
          >> (!(x % 2) * 4))
         & 0b1111;
}

